export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === 'OPTIONS') return cors(new Response(null, { status: 204 }));

    if (url.pathname.startsWith('/api/')) {
      return handleApi(request, env, url);
    }

    if (url.pathname === '/health') {
      return json({ ok: true, version: APP_VERSION, kv: Boolean(env.TRADING_JOURNAL), enterpriseBlueprints: ENTERPRISE_FEATURE_CATALOG.length });
    }

    return new Response(renderApp(), {
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'no-store, max-age=0',
        'x-app-version': APP_VERSION
      }
    });
  }
};

async function handleApi(request, env, url) {
  const workspace = sanitizeWorkspace(url.searchParams.get('workspace') || request.headers.get('x-workspace') || DEFAULT_WORKSPACE);
  const key = STATE_KEY_PREFIX + workspace;
  const path = url.pathname.replace(/^\/api\/?/, '');

  if (!env.TRADING_JOURNAL) {
    return json({ error: 'KV binding TRADING_JOURNAL is not available. Bind the namespace with variable name TRADING_JOURNAL.' }, 500);
  }

  if (request.method === 'GET' && path === 'catalog') {
    const offset = Math.max(0, Number(url.searchParams.get('offset') || 0));
    const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit') || 50)));
    return json({ total: ENTERPRISE_FEATURE_CATALOG.length, offset, limit, items: ENTERPRISE_FEATURE_CATALOG.slice(offset, offset + limit) });
  }

  if (request.method === 'GET' && (path === 'state' || path === '')) {
    const state = await loadState(env, key);
    return json({ workspace, state });
  }

  if (request.method === 'POST' && path === 'state') {
    const payload = await readJson(request);
    const incoming = normalizeState(payload.state || payload);
    incoming.updatedAt = new Date().toISOString();
    await env.TRADING_JOURNAL.put(key, JSON.stringify(incoming));
    return json({ ok: true, workspace, state: incoming });
  }

  if (request.method === 'POST' && path === 'reset') {
    const fresh = normalizeState(DEFAULT_STATE);
    fresh.updatedAt = new Date().toISOString();
    await env.TRADING_JOURNAL.put(key, JSON.stringify(fresh));
    return json({ ok: true, workspace, state: fresh });
  }

  if (request.method === 'GET' && path === 'export') {
    const state = await loadState(env, key);
    return new Response(JSON.stringify(state, null, 2), {
      headers: {
        'content-type': 'application/json; charset=utf-8',
        'content-disposition': `attachment; filename="trading-journal-${workspace}.json"`
      }
    });
  }

  if (request.method === 'POST' && path === 'import') {
    const payload = await readJson(request);
    const imported = normalizeState(payload);
    imported.updatedAt = new Date().toISOString();
    await env.TRADING_JOURNAL.put(key, JSON.stringify(imported));
    return json({ ok: true, workspace, state: imported });
  }

  const collectionMatch = path.match(/^(trades|journal|accounts|strategies|backtests|events|news|watchlist|playbooks)(?:\/([^/]+))?$/);
  if (collectionMatch) {
    const [, collection, id] = collectionMatch;
    const state = await loadState(env, key);
    state[collection] = Array.isArray(state[collection]) ? state[collection] : [];

    if (request.method === 'GET') {
      if (id) return json(state[collection].find((item) => item.id === id) || null);
      return json(state[collection]);
    }

    if (request.method === 'POST') {
      const payload = await readJson(request);
      const item = { ...payload, id: payload.id || crypto.randomUUID(), updatedAt: new Date().toISOString() };
      state[collection].unshift(item);
      state.updatedAt = new Date().toISOString();
      await env.TRADING_JOURNAL.put(key, JSON.stringify(state));
      return json({ ok: true, item, state });
    }

    if (request.method === 'PUT' && id) {
      const payload = await readJson(request);
      const index = state[collection].findIndex((item) => item.id === id);
      if (index < 0) return json({ error: 'Not found' }, 404);
      state[collection][index] = { ...state[collection][index], ...payload, id, updatedAt: new Date().toISOString() };
      state.updatedAt = new Date().toISOString();
      await env.TRADING_JOURNAL.put(key, JSON.stringify(state));
      return json({ ok: true, item: state[collection][index], state });
    }

    if (request.method === 'DELETE' && id) {
      state[collection] = state[collection].filter((item) => item.id !== id);
      state.updatedAt = new Date().toISOString();
      await env.TRADING_JOURNAL.put(key, JSON.stringify(state));
      return json({ ok: true, state });
    }
  }

  return json({ error: 'Not found' }, 404);
}

async function loadState(env, key) {
  const raw = await env.TRADING_JOURNAL.get(key);
  if (!raw) {
    const seeded = normalizeState(DEFAULT_STATE);
    seeded.updatedAt = new Date().toISOString();
    await env.TRADING_JOURNAL.put(key, JSON.stringify(seeded));
    return seeded;
  }
  return normalizeState(JSON.parse(raw));
}

function normalizeState(input) {
  const state = structuredClone(DEFAULT_STATE);
  const source = input && typeof input === 'object' ? input : {};
  for (const [key, value] of Object.entries(source)) {
    if (Array.isArray(state[key])) state[key] = Array.isArray(value) ? value : state[key];
    else if (state[key] && typeof state[key] === 'object') state[key] = { ...state[key], ...(value || {}) };
    else state[key] = value;
  }
  state.version = APP_VERSION;
  return state;
}

async function readJson(request) {
  const text = await request.text();
  return text ? JSON.parse(text) : {};
}

function sanitizeWorkspace(value) {
  return String(value || DEFAULT_WORKSPACE).toLowerCase().replace(/[^a-z0-9_-]/g, '-').slice(0, 64) || DEFAULT_WORKSPACE;
}

function json(data, status = 200) {
  return cors(new Response(JSON.stringify(data), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8' }
  }));
}

function cors(response) {
  const headers = new Headers(response.headers);
  headers.set('access-control-allow-origin', '*');
  headers.set('access-control-allow-methods', 'GET,POST,PUT,DELETE,OPTIONS');
  headers.set('access-control-allow-headers', 'content-type,x-workspace');
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

function renderApp() {
  return `<!doctype html>
<html lang="fa" dir="rtl">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="theme-color" content="#050816" />
  <title>Trading OS Pro - ژورنال و داشبورد تریدینگ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #050816;
      --panel: rgba(255,255,255,.09);
      --panel-strong: rgba(255,255,255,.15);
      --stroke: rgba(255,255,255,.18);
      --text: #f8fafc;
      --muted: #a8b3cf;
      --primary: #8b5cf6;
      --primary-2: #06b6d4;
      --green: #22c55e;
      --red: #ef4444;
      --yellow: #f59e0b;
      --blue: #3b82f6;
      --shadow: 0 24px 90px rgba(0,0,0,.42);
      --blur: blur(22px) saturate(145%);
      --radius: 28px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Tahoma, Arial, sans-serif;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      min-height: 100vh;
      background:
        radial-gradient(circle at 10% 0%, rgba(124,58,237,.45), transparent 36%),
        radial-gradient(circle at 88% 8%, rgba(6,182,212,.36), transparent 35%),
        radial-gradient(circle at 55% 95%, rgba(34,197,94,.13), transparent 40%),
        linear-gradient(135deg, #050816 0%, #0f172a 46%, #111827 100%);
      color: var(--text);
      overflow-x: hidden;
    }
    body:before {
      content: "";
      position: fixed;
      inset: 0;
      pointer-events: none;
      background-image: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.03) 1px, transparent 1px);
      background-size: 42px 42px;
      mask-image: radial-gradient(circle at center, #000 0%, transparent 72%);
      z-index: 0;
    }
    button, input, select, textarea { font: inherit; }
    button { cursor: pointer; }
    a { color: inherit; }
    .app-shell { position: relative; z-index: 1; display: grid; grid-template-columns: 310px 1fr; gap: 22px; padding: 22px; min-height: 100vh; }
    .glass { background: var(--panel); border: 1px solid var(--stroke); box-shadow: var(--shadow); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur); }
    .sidebar { border-radius: var(--radius); padding: 20px; position: sticky; top: 22px; height: calc(100vh - 44px); overflow: hidden auto; }
    .brand { display:flex; align-items:center; gap:14px; margin-bottom:22px; }
    .logo { width:52px; height:52px; border-radius:18px; background: conic-gradient(from 180deg, var(--primary), var(--primary-2), var(--green), var(--primary)); box-shadow: 0 0 32px rgba(139,92,246,.52); position:relative; }
    .logo:after { content:""; position:absolute; inset:10px; border-radius:12px; background:rgba(5,8,22,.72); border:1px solid rgba(255,255,255,.25); }
    .brand h1 { font-size: 1.08rem; margin:0; letter-spacing:-.02em; }
    .brand p { margin:.2rem 0 0; color:var(--muted); font-size:.78rem; }
    .nav { display:grid; gap:9px; }
    .nav button, .quick-action, .btn {
      border: 1px solid transparent;
      border-radius: 18px;
      padding: 12px 14px;
      color: var(--text);
      background: rgba(255,255,255,.055);
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap: 12px;
      transition: .18s ease;
    }
    .nav button:hover, .nav button.active, .btn:hover, .quick-action:hover { transform: translateY(-1px); border-color: rgba(255,255,255,.22); background: rgba(255,255,255,.11); }
    .nav span:first-child { display:flex; align-items:center; gap:10px; }
    .nav small { color:var(--muted); }
    .side-section { margin-top: 20px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.11); }
    .side-section h3 { margin:0 0 10px; font-size:.82rem; color: var(--muted); font-weight:600; }
    .status-dot { width:9px; height:9px; border-radius:50%; background:var(--green); box-shadow: 0 0 15px var(--green); display:inline-block; }
    .main { min-width:0; display:grid; gap:22px; }
    .topbar { border-radius: var(--radius); padding: 18px; display:flex; align-items:center; justify-content:space-between; gap:16px; }
    .search { flex:1; max-width: 520px; position:relative; }
    .search input { width:100%; border:1px solid var(--stroke); outline:0; color:var(--text); padding:14px 46px 14px 16px; border-radius:18px; background:rgba(255,255,255,.08); }
    .search b { position:absolute; right:16px; top:50%; transform:translateY(-50%); color:var(--muted); }
    .toolbar { display:flex; gap:10px; flex-wrap:wrap; }
    .btn { justify-content:center; min-height:44px; }
    .btn.primary { background: linear-gradient(135deg, rgba(139,92,246,.95), rgba(6,182,212,.78)); border-color: rgba(255,255,255,.2); }
    .btn.danger { background: rgba(239,68,68,.16); color: #fecaca; }
    .btn.success { background: rgba(34,197,94,.16); color:#bbf7d0; }
    .hero { border-radius: calc(var(--radius) + 8px); padding: 28px; overflow:hidden; position:relative; display:grid; grid-template-columns: 1.4fr .8fr; gap:24px; }
    .hero:before { content:""; position:absolute; left:-90px; top:-110px; width:330px; height:330px; background:radial-gradient(circle, rgba(6,182,212,.34), transparent 64%); }
    .hero h2 { margin:0; font-size: clamp(2rem, 4vw, 4.2rem); line-height:1.03; letter-spacing:-.065em; }
    .hero p { color: var(--muted); max-width: 760px; line-height:1.9; }
    .hero-metrics { display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap:12px; }
    .metric, .card { border:1px solid rgba(255,255,255,.14); background: rgba(255,255,255,.075); border-radius:24px; padding:18px; }
    .metric label, .muted { color:var(--muted); font-size:.85rem; }
    .metric strong { display:block; font-size:1.65rem; margin-top:8px; direction:ltr; text-align:right; }
    .positive { color:#86efac !important; }
    .negative { color:#fca5a5 !important; }
    .warning { color:#fcd34d !important; }
    .grid { display:grid; grid-template-columns: repeat(12, minmax(0,1fr)); gap:18px; }
    .span-12 { grid-column: span 12; } .span-8 { grid-column: span 8; } .span-7 { grid-column: span 7; } .span-6 { grid-column: span 6; } .span-5 { grid-column: span 5; } .span-4 { grid-column: span 4; } .span-3 { grid-column: span 3; }
    .card { min-height: 120px; position:relative; overflow:hidden; }
    .card-header { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:14px; }
    .card h3 { margin:0; font-size:1.02rem; }
    .pill { border:1px solid rgba(255,255,255,.15); background:rgba(255,255,255,.08); color:var(--muted); border-radius:999px; padding:6px 10px; font-size:.75rem; display:inline-flex; align-items:center; gap:6px; }
    .kpi { font-size:2rem; font-weight:800; letter-spacing:-.05em; direction:ltr; text-align:right; }
    .sparkline { width:100%; height:70px; direction:ltr; }
    .table-wrap { overflow:auto; border-radius:18px; border:1px solid rgba(255,255,255,.1); }
    table { width:100%; border-collapse: collapse; min-width: 820px; }
    th, td { text-align:right; padding:13px 14px; border-bottom:1px solid rgba(255,255,255,.08); white-space:nowrap; }
    th { color:var(--muted); font-size:.78rem; font-weight:700; background:rgba(255,255,255,.05); }
    tr:hover td { background:rgba(255,255,255,.035); }
    .progress { height:10px; background:rgba(255,255,255,.09); border-radius:999px; overflow:hidden; }
    .progress i { display:block; height:100%; background:linear-gradient(90deg, var(--primary), var(--primary-2)); border-radius:inherit; }
    .view { display:none; animation: show .22s ease; }
    .view.active { display:block; }
    @keyframes show { from { opacity:0; transform: translateY(8px); } to { opacity:1; transform: none; } }
    .form-grid { display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap:14px; }
    .field { display:grid; gap:7px; }
    .field.full { grid-column: 1 / -1; }
    .field label { color:var(--muted); font-size:.82rem; }
    .field input, .field select, .field textarea {
      width:100%; border:1px solid rgba(255,255,255,.16); border-radius:16px; background:rgba(255,255,255,.075); color:var(--text); padding:12px 13px; outline:0;
    }
    .field textarea { min-height:110px; resize:vertical; line-height:1.8; }
    option { background:#111827; color:#fff; }
    .modal { position:fixed; inset:0; z-index: 50; display:none; place-items:center; padding:20px; background:rgba(2,6,23,.72); backdrop-filter: blur(12px); }
    .modal.active { display:grid; }
    .modal-panel { width:min(960px, 100%); max-height:92vh; overflow:auto; border-radius:30px; padding:22px; }
    .toast-zone { position: fixed; left: 22px; bottom: 22px; z-index: 80; display:grid; gap:10px; }
    .toast { padding:12px 14px; border-radius:16px; background:rgba(15,23,42,.82); border:1px solid rgba(255,255,255,.17); box-shadow: var(--shadow); }
    .chips { display:flex; gap:8px; flex-wrap:wrap; }
    .chip { padding:7px 10px; border-radius:999px; background:rgba(139,92,246,.16); color:#ddd6fe; font-size:.78rem; border:1px solid rgba(139,92,246,.26); }
    .timeline { display:grid; gap:10px; }
    .timeline-item { display:grid; grid-template-columns: 86px 1fr; gap:12px; padding:12px; border-radius:18px; background:rgba(255,255,255,.055); border:1px solid rgba(255,255,255,.1); }
    .impact-High { color:#fecaca; } .impact-Medium { color:#fde68a; } .impact-Low { color:#bbf7d0; }
    .kanban { display:grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap:14px; }
    .lane { border-radius:22px; padding:14px; background:rgba(255,255,255,.055); border:1px solid rgba(255,255,255,.1); min-height:240px; }
    .lane h4 { margin:0 0 12px; }
    .check-item { display:flex; gap:10px; align-items:flex-start; padding:9px 0; color:var(--muted); }
    .check-item input { accent-color: var(--primary); margin-top:4px; }
    .heatmap { display:grid; grid-template-columns: repeat(7, 1fr); gap:6px; direction:ltr; }
    .heatmap i { aspect-ratio:1; border-radius:8px; background:rgba(255,255,255,.08); border:1px solid rgba(255,255,255,.08); }
    .price-tile { display:flex; justify-content:space-between; align-items:center; padding:12px; border-radius:18px; background:rgba(255,255,255,.055); border:1px solid rgba(255,255,255,.1); margin-bottom:9px; direction:ltr; }
    .price-tile b { font-size:1.05rem; }
    .footer-note { color:var(--muted); text-align:center; padding:20px; line-height:1.8; }
    @media (max-width: 1180px) { .app-shell { grid-template-columns: 1fr; } .sidebar { position:relative; top:auto; height:auto; } .hero { grid-template-columns:1fr; } .span-8,.span-7,.span-6,.span-5,.span-4,.span-3 { grid-column: span 12; } }
    @media (max-width: 720px) { .app-shell { padding:12px; } .topbar { align-items:stretch; flex-direction:column; } .form-grid, .kanban { grid-template-columns:1fr; } .hero-metrics { grid-template-columns:1fr; } .hero h2 { font-size:2.1rem; } }
  </style>
</head>
<body>
  <div class="app-shell">
    <aside class="sidebar glass">
      <div class="brand"><div class="logo"></div><div><h1>Trading OS Pro</h1><p>ژورنال، ریسک، بک‌تست، ماکرو و قیمت زنده</p></div></div>
      <nav class="nav" id="nav"></nav>
      <section class="side-section">
        <h3>وضعیت سیستم</h3>
        <div class="quick-action"><span><span class="status-dot"></span> KV: TRADING_JOURNAL</span><small id="saveState">آماده</small></div>
        <button class="quick-action" onclick="exportState()"><span>⬇️ خروجی JSON</span><small>Backup</small></button>
        <button class="quick-action" onclick="document.getElementById('importFile').click()"><span>⬆️ ایمپورت</span><small>Restore</small></button>
        <input id="importFile" type="file" accept="application/json" hidden />
      </section>
      <section class="side-section">
        <h3>چک‌لیست سریع</h3>
        <div id="quickChecklist"></div>
      </section>
    </aside>

    <main class="main">
      <header class="topbar glass">
        <div class="search"><b>⌕</b><input id="globalSearch" placeholder="جستجو در معاملات، ژورنال، استراتژی‌ها و اخبار..." /></div>
        <div class="toolbar">
          <button class="btn primary" onclick="openTradeModal()">+ معامله جدید</button>
          <button class="btn" onclick="openJournalModal()">ثبت روانشناسی</button>
          <button class="btn" onclick="saveState()">ذخیره دستی</button>
        </div>
      </header>

      <section class="hero glass">
        <div>
          <span class="pill">نسخه ${APP_VERSION} • Single Cloudflare Worker</span>
          <h2>مرکز فرماندهی تریدینگ با ژورنال حرفه‌ای</h2>
          <p>همه‌چیز در یک فایل Worker: داشبورد سفارشی، ژورنال معاملات، تحلیل احساسات، بک‌تست استراتژی، ریسک منیجر، تقویم رویدادهای کلان، چند حساب و قیمت زنده با WebSocket مرورگر.</p>
          <div class="chips" id="heroChips"></div>
        </div>
        <div class="hero-metrics" id="heroMetrics"></div>
      </section>

      <section id="views"></section>
      <p class="footer-note">داده‌ها در KV با namespace variable <b>TRADING_JOURNAL</b> ذخیره می‌شوند. برای هر workspace از query string مثل <code>?workspace=prop</code> استفاده کن.</p>
    </main>
  </div>

  <div class="modal" id="modal"><div class="modal-panel glass"><div id="modalContent"></div></div></div>
  <div class="toast-zone" id="toasts"></div>

<script>
const NAV = [
  ['dashboard','داشبورد','نمای کلی','📊'], ['journal','ژورنال','معاملات و ذهن','🧠'], ['risk','ریسک منیجر','سایزبندی','🛡️'],
  ['backtest','بک‌تست','استراتژی','🧪'], ['macro','اقتصاد کلان','خبر و رویداد','🌍'], ['live','لایو قیمت','WebSocket','⚡'],
  ['accounts','چند حساب','سرمایه','🏦'], ['playbook','پلی‌بوک','فرایندها','📚'], ['settings','تنظیمات','دیتا','⚙️']
];
const API = '/api/state' + location.search;
let state = null;
let activeView = 'dashboard';
let searchTerm = '';
let liveSocket = null;
let livePrices = {};

const $ = (id) => document.getElementById(id);
const fmt = (n, digits=2) => new Intl.NumberFormat('en-US', { maximumFractionDigits: digits }).format(Number(n || 0));
const money = (n) => '$' + fmt(n, 2);
const pct = (n) => fmt(n, 2) + '%';
const uid = (prefix='id') => prefix + '-' + crypto.randomUUID();
const clone = (x) => JSON.parse(JSON.stringify(x));

init();

async function init() {
  renderNav();
  bindEvents();
  await loadState();
  routeFromHash();
  window.addEventListener('hashchange', routeFromHash);
  setInterval(() => { if (state) renderHero(); }, 15000);
}

function bindEvents() {
  $('globalSearch').addEventListener('input', (event) => { searchTerm = event.target.value.trim().toLowerCase(); renderActive(); });
  $('importFile').addEventListener('change', importState);
  $('modal').addEventListener('click', (event) => { if (event.target.id === 'modal') closeModal(); });
}

async function loadState() {
  setSaveState('در حال بارگذاری...');
  const response = await fetch(API);
  const payload = await response.json();
  state = payload.state;
  setSaveState('همگام');
  renderAll();
}

async function saveState(show = true) {
  state.updatedAt = new Date().toISOString();
  setSaveState('در حال ذخیره...');
  const response = await fetch(API, { method:'POST', headers:{ 'content-type':'application/json' }, body: JSON.stringify({ state }) });
  const payload = await response.json();
  state = payload.state || state;
  setSaveState('ذخیره شد');
  if (show) toast('ذخیره شد');
  renderAll();
}

function setSaveState(text) { $('saveState').textContent = text; }
function toast(text) { const el = document.createElement('div'); el.className='toast'; el.textContent=text; $('toasts').appendChild(el); setTimeout(()=>el.remove(), 3200); }
function routeFromHash() { const hash = location.hash.replace('#',''); activeView = NAV.some(n => n[0] === hash) ? hash : 'dashboard'; renderAll(); }
function navigate(view) { location.hash = view; }

function renderNav() {
  $('nav').innerHTML = NAV.map(([id, label, small, icon]) => '<button data-view="'+id+'" onclick="navigate(\''+id+'\')"><span><b>'+icon+'</b>'+label+'</span><small>'+small+'</small></button>').join('');
}

function renderAll() {
  if (!state) return;
  document.querySelectorAll('.nav button').forEach(btn => btn.classList.toggle('active', btn.dataset.view === activeView));
  renderHero();
  renderChecklist();
  renderActive();
}

function renderHero() {
  const stats = computeStats();
  $('heroChips').innerHTML = [
    'Win Rate ' + pct(stats.winRate), 'Profit Factor ' + fmt(stats.profitFactor), 'Expectancy ' + money(stats.expectancy), 'Discipline ' + fmt(stats.avgDiscipline, 1) + '/10'
  ].map(x => '<span class="chip">'+x+'</span>').join('');
  $('heroMetrics').innerHTML = [
    ['Net P&L', money(stats.net), stats.net >= 0 ? 'positive' : 'negative'], ['Equity', money(stats.equity), ''], ['Max DD', pct(stats.maxDrawdown), 'warning'], ['Trades', stats.trades.length, '']
  ].map(([label, value, cls]) => '<div class="metric"><label>'+label+'</label><strong class="'+cls+'">'+value+'</strong></div>').join('');
}

function renderChecklist() {
  const items = (state.playbooks[0]?.items || []).slice(0,5);
  $('quickChecklist').innerHTML = items.map((item, index) => '<label class="check-item"><input type="checkbox" id="qc'+index+'"><span>'+item+'</span></label>').join('');
}

function renderActive() {
  const renderers = { dashboard, journal, risk, backtest, macro, live, accounts, playbook, settings };
  $('views').innerHTML = '<div class="view active">' + renderers[activeView]() + '</div>';
  afterRender(activeView);
}

function afterRender(view) {
  if (view === 'dashboard') drawEquitySparkline('equitySpark', computeEquityCurve());
  if (view === 'risk') calculateRisk();
  if (view === 'backtest') calculateBacktest();
  if (view === 'live') startLivePrices(); else stopLivePrices();
}

function computeStats() {
  const trades = state.trades || [];
  const rows = trades.map(t => ({ ...t, pnl: tradePnl(t), risk: tradeRisk(t), r: tradeR(t) }));
  const wins = rows.filter(t => t.pnl > 0), losses = rows.filter(t => t.pnl < 0);
  const grossWin = wins.reduce((s,t)=>s+t.pnl,0), grossLoss = Math.abs(losses.reduce((s,t)=>s+t.pnl,0));
  const net = rows.reduce((s,t)=>s+t.pnl,0);
  const totalStart = state.accounts.reduce((s,a)=>s+Number(a.startingBalance || 0),0);
  const equity = state.accounts.reduce((s,a)=>s+Number(a.balance || 0),0);
  return {
    trades: rows,
    net,
    equity,
    winRate: rows.length ? wins.length / rows.length * 100 : 0,
    profitFactor: grossLoss ? grossWin / grossLoss : grossWin ? 99 : 0,
    expectancy: rows.length ? net / rows.length : 0,
    avgDiscipline: rows.length ? rows.reduce((s,t)=>s+Number(t.discipline||0),0)/rows.length : 0,
    maxDrawdown: maxDrawdown(computeEquityCurve(totalStart)),
    totalStart
  };
}
function tradePnl(t) { const sign = t.side === 'Short' ? -1 : 1; return ((Number(t.exit||0)-Number(t.entry||0))*sign*Number(t.qty||0))-Number(t.fees||0); }
function tradeRisk(t) { return Math.abs(Number(t.entry||0)-Number(t.stop||0))*Number(t.qty||0) || 0; }
function tradeR(t) { const r = tradeRisk(t); return r ? tradePnl(t)/r : 0; }
function computeEquityCurve(start) { let eq = start || state.accounts.reduce((s,a)=>s+Number(a.startingBalance||0),0) || 10000; return [eq].concat([...state.trades].sort((a,b)=>new Date(a.closedAt)-new Date(b.closedAt)).map(t => eq += tradePnl(t))); }
function maxDrawdown(curve) { let peak = curve[0] || 0, max = 0; curve.forEach(v => { peak = Math.max(peak, v); max = Math.max(max, peak ? (peak-v)/peak*100 : 0); }); return max; }

function dashboard() {
  const stats = computeStats();
  const best = [...stats.trades].sort((a,b)=>b.pnl-a.pnl)[0];
  const worst = [...stats.trades].sort((a,b)=>a.pnl-b.pnl)[0];
  return '<div class="grid">' +
    kpiCard('بازده خالص', money(stats.net), 'span-3', stats.net >= 0 ? 'positive':'negative') +
    kpiCard('نرخ برد', pct(stats.winRate), 'span-3') +
    kpiCard('میانگین R', fmt(stats.trades.reduce((s,t)=>s+t.r,0)/(stats.trades.length||1),2), 'span-3') +
    kpiCard('افت سرمایه', pct(stats.maxDrawdown), 'span-3 warning') +
    '<div class="card span-8"><div class="card-header"><h3>منحنی سرمایه</h3><span class="pill">Realized P&L</span></div><svg id="equitySpark" class="sparkline"></svg></div>' +
    '<div class="card span-4"><div class="card-header"><h3>بهترین/بدترین</h3></div><p class="muted">بهترین: '+(best ? best.symbol+' '+money(best.pnl) : '-')+'</p><p class="muted">بدترین: '+(worst ? worst.symbol+' '+money(worst.pnl) : '-')+'</p><div class="progress"><i style="width:'+Math.min(100,stats.winRate)+'%"></i></div></div>' +
    '<div class="card span-7"><div class="card-header"><h3>آخرین معاملات</h3><button class="btn" onclick="navigate(\'journal\')">مشاهده همه</button></div>'+tradesTable(stats.trades.slice(0,6))+'</div>' +
    '<div class="card span-5"><div class="card-header"><h3>رویدادهای نزدیک</h3><span class="pill">Macro</span></div>'+eventsList(state.events.slice(0,5))+'</div>' +
    '<div class="card span-6"><div class="card-header"><h3>احساسات و انضباط</h3></div>'+psychologyPanel()+'</div>' +
    '<div class="card span-6"><div class="card-header"><h3>واچ‌لیست</h3></div>'+watchlistStatic()+'</div>' +
  '</div>';
}
function kpiCard(label, value, span='span-3', cls='') { return '<div class="card '+span+'"><div class="muted">'+label+'</div><div class="kpi '+cls+'">'+value+'</div></div>'; }

function journal() {
  const stats = computeStats();
  const trades = filterItems(stats.trades, ['symbol','setup','market','notes','mistakes','emotionBefore','emotionAfter']);
  return '<div class="grid"><div class="card span-12"><div class="card-header"><h3>ژورنال معاملات حرفه‌ای</h3><div class="toolbar"><button class="btn primary" onclick="openTradeModal()">+ معامله</button><button class="btn" onclick="openJournalModal()">ثبت روزانه ذهن</button></div></div>'+tradesTable(trades, true)+'</div><div class="card span-6"><h3>ژورنال روانشناسی روزانه</h3>'+journalCards()+'</div><div class="card span-6"><h3>تحلیل اشتباهات</h3>'+mistakeAnalytics(stats.trades)+'</div></div>';
}
function tradesTable(trades, actions=false) {
  return '<div class="table-wrap"><table><thead><tr><th>نماد</th><th>حساب</th><th>جهت</th><th>ستاپ</th><th>ورود</th><th>خروج</th><th>R</th><th>P&L</th><th>ذهن</th>'+(actions?'<th>اکشن</th>':'')+'</tr></thead><tbody>' +
    trades.map(t => '<tr><td><b>'+t.symbol+'</b><br><small class="muted">'+(t.timeframe||'')+'</small></td><td>'+accountName(t.accountId)+'</td><td>'+sideBadge(t.side)+'</td><td>'+escapeHtml(t.setup||'')+'</td><td>'+fmt(t.entry)+'</td><td>'+fmt(t.exit)+'</td><td>'+fmt(t.r,2)+'</td><td class="'+(t.pnl>=0?'positive':'negative')+'">'+money(t.pnl)+'</td><td>'+escapeHtml(t.emotionAfter||t.emotionBefore||'-')+'</td>'+(actions?'<td><button class="btn" onclick="editTrade(\''+t.id+'\')">ویرایش</button> <button class="btn danger" onclick="deleteTrade(\''+t.id+'\')">حذف</button></td>':'')+'</tr>').join('') +
    '</tbody></table></div>';
}
function sideBadge(side) { return '<span class="pill '+(side==='Long'?'positive':'negative')+'">'+side+'</span>'; }
function accountName(id) { return state.accounts.find(a=>a.id===id)?.name || 'بدون حساب'; }

function journalCards() {
  return (state.journal||[]).map(j => '<div class="metric" style="margin-top:10px"><label>'+j.date+' • مود '+j.mood+'/10 • استرس '+j.stress+'/10</label><p>'+escapeHtml(j.plan||'')+'</p><p class="muted">'+escapeHtml(j.review||'')+'</p></div>').join('') || '<p class="muted">هنوز ثبت نشده.</p>';
}
function mistakeAnalytics(trades) {
  const mistakes = trades.filter(t=>t.mistakes).map(t=>t.mistakes);
  const lowDiscipline = trades.filter(t=>Number(t.discipline||0)<7).length;
  return '<p class="muted">معاملات با انضباط زیر ۷: '+lowDiscipline+'</p><div class="timeline">'+mistakes.map((m,i)=>'<div class="timeline-item"><b>#'+(i+1)+'</b><span>'+escapeHtml(m)+'</span></div>').join('')+'</div>';
}
function psychologyPanel() {
  const stats = computeStats();
  const avgConf = stats.trades.reduce((s,t)=>s+Number(t.confidence||0),0)/(stats.trades.length||1);
  const avgDisc = stats.avgDiscipline;
  return '<div class="grid"><div class="span-6"><label class="muted">انضباط</label><div class="progress"><i style="width:'+(avgDisc*10)+'%"></i></div><h2>'+fmt(avgDisc,1)+'/10</h2></div><div class="span-6"><label class="muted">اعتماد به نفس</label><div class="progress"><i style="width:'+(avgConf*10)+'%"></i></div><h2>'+fmt(avgConf,1)+'/10</h2></div></div><div class="heatmap">'+Array.from({length:35},(_,i)=>'<i style="opacity:'+(0.25+Math.random()*0.75).toFixed(2)+'"></i>').join('')+'</div>';
}

function risk() {
  return '<div class="grid"><div class="card span-5"><div class="card-header"><h3>ماشین حساب پوزیشن سایزینگ</h3><span class="pill">Risk Manager</span></div><div class="form-grid">'+
    field('capital','سرمایه حساب','number',state.accounts[0]?.balance||10000)+field('riskPercent','ریسک درصدی','number',state.settings.riskPerTrade)+field('entry','قیمت ورود','number',100)+field('stop','استاپ لاس','number',98)+field('leverage','اهرم','number',1)+field('fee','کارمزد تقریبی','number',0)+
    '<div class="field full"><button class="btn primary" onclick="calculateRisk()">محاسبه</button></div></div></div><div class="card span-7"><h3>نتیجه ریسک</h3><div id="riskResult"></div></div><div class="card span-12"><h3>گاردریل‌های ریسک</h3>'+riskGuardrails()+'</div></div>';
}
function field(id,label,type='text',value='') { return '<div class="field"><label>'+label+'</label><input id="'+id+'" type="'+type+'" value="'+value+'" step="any"></div>'; }
function calculateRisk() {
  if (!$('riskResult')) return;
  const capital = Number($('capital').value||0), riskPercent = Number($('riskPercent').value||0), entry = Number($('entry').value||0), stop = Number($('stop').value||0), leverage = Number($('leverage').value||1), fee = Number($('fee').value||0);
  const riskCash = capital * riskPercent / 100;
  const perUnitRisk = Math.abs(entry - stop);
  const qty = perUnitRisk ? Math.max(0, (riskCash-fee) / perUnitRisk) : 0;
  const notional = qty * entry;
  const margin = leverage ? notional / leverage : notional;
  $('riskResult').innerHTML = '<div class="grid">'+kpiCard('ریسک نقدی', money(riskCash), 'span-6')+kpiCard('حجم مجاز', fmt(qty,6), 'span-6')+kpiCard('ارزش پوزیشن', money(notional), 'span-6')+kpiCard('مارجین تقریبی', money(margin), 'span-6')+'</div><p class="muted">اگر حد ضرر فعال شود، زیان هدف حدود '+money(riskCash)+' است.</p>';
}
function riskGuardrails() {
  const stats = computeStats();
  const daily = Math.abs(stats.trades.filter(t => (t.closedAt||'').slice(0,10) === new Date().toISOString().slice(0,10)).reduce((s,t)=>s+Math.min(0,t.pnl),0));
  const maxDaily = stats.equity * state.settings.maxDailyLoss / 100;
  return '<div class="grid">'+kpiCard('حداکثر زیان روزانه', money(maxDaily), 'span-4')+kpiCard('زیان امروز', money(daily), 'span-4 '+(daily>maxDaily?'negative':'positive'))+kpiCard('ریسک پیش‌فرض', pct(state.settings.riskPerTrade), 'span-4')+'</div>';
}

function backtest() {
  const options = state.strategies.map(s=>'<option value="'+s.id+'">'+s.name+'</option>').join('');
  return '<div class="grid"><div class="card span-5"><h3>بک‌تست سریع استراتژی</h3><div class="form-grid">'+
    '<div class="field full"><label>استراتژی</label><select id="btStrategy">'+options+'</select></div>'+field('btCapital','سرمایه اولیه','number',10000)+field('btRisk','ریسک هر معامله %','number',1)+'<div class="field full"><label>نتایج بر حسب R (با کاما جدا کن)</label><textarea id="btTrades">1.5,-1,2.2,-0.5,3,-1,0.8,1.2</textarea></div><div class="field full"><button class="btn primary" onclick="calculateBacktest()">اجرای بک‌تست</button></div></div></div><div class="card span-7"><h3>گزارش بک‌تست</h3><div id="btResult"></div></div><div class="card span-12"><h3>استراتژی‌ها</h3>'+strategyCards()+'</div></div>';
}
function calculateBacktest() {
  if (!$('btResult')) return;
  const capital = Number($('btCapital').value || 10000), risk = Number($('btRisk').value || 1);
  const rs = $('btTrades').value.split(',').map(x=>Number(x.trim())).filter(Number.isFinite);
  let eq = capital; const curve = [eq]; rs.forEach(r => { eq += eq * risk / 100 * r; curve.push(eq); });
  const wins = rs.filter(r=>r>0).length;
  $('btResult').innerHTML = '<div class="grid">'+kpiCard('سرمایه نهایی', money(eq), 'span-6 '+(eq>=capital?'positive':'negative'))+kpiCard('بازده', pct((eq-capital)/capital*100), 'span-6')+kpiCard('Win Rate', pct(rs.length?wins/rs.length*100:0), 'span-6')+kpiCard('Max DD', pct(maxDrawdown(curve)), 'span-6 warning')+'</div><svg id="btSpark" class="sparkline"></svg>';
  drawEquitySparkline('btSpark', curve);
}
function strategyCards() { return '<div class="kanban">'+state.strategies.map(s=>'<div class="lane"><h4>'+escapeHtml(s.name)+'</h4><p class="muted">'+escapeHtml(s.market)+' • '+escapeHtml(s.timeframe)+'</p>'+s.rules.map(r=>'<label class="check-item"><input type="checkbox"><span>'+escapeHtml(r)+'</span></label>').join('')+'</div>').join('')+'</div>'; }

function macro() {
  return '<div class="grid"><div class="card span-7"><div class="card-header"><h3>تقویم اقتصاد کلان</h3><button class="btn" onclick="openEventModal()">+ رویداد</button></div>'+eventsList(state.events)+'</div><div class="card span-5"><h3>News Desk</h3>'+newsList()+'</div><div class="card span-12"><h3>نقشه تصمیم ماکرو</h3><div class="kanban"><div class="lane"><h4>Risk-on</h4><p class="muted">DXY ضعیف، بازده نزولی، سهام قوی، کریپتو با جریان ورودی.</p></div><div class="lane"><h4>Neutral</h4><p class="muted">قبل از خبرهای High Impact فقط اسکالپ کوچک یا عدم معامله.</p></div><div class="lane"><h4>Risk-off</h4><p class="muted">DXY و بازده قوی، نقدینگی کم، پرهیز از لانگ‌های تهاجمی.</p></div></div></div></div>';
}
function eventsList(events) { return '<div class="timeline">'+events.map(e=>'<div class="timeline-item"><div><b>'+e.time+'</b><br><small>'+e.date+'</small></div><div><b class="impact-'+e.impact+'">'+escapeHtml(e.title)+'</b><p class="muted">'+e.currency+' • '+e.impact+' • '+escapeHtml(e.plan||'')+'</p></div></div>').join('')+'</div>'; }
function newsList() { return '<div class="timeline">'+state.news.map(n=>'<div class="timeline-item"><b>'+escapeHtml(n.source)+'</b><span><b>'+escapeHtml(n.title)+'</b><br><small class="muted">'+n.impact+' • '+new Date(n.createdAt).toLocaleString('fa-IR')+'</small></span></div>').join('')+'</div>'; }

function live() {
  return '<div class="grid"><div class="card span-8"><div class="card-header"><h3>قیمت زنده WebSocket</h3><span class="pill" id="wsStatus">در حال اتصال...</span></div><div id="livePrices"></div></div><div class="card span-4"><h3>هشدارها</h3><p class="muted">هشدارهای بالاتر/پایین‌تر واچ‌لیست در مرورگر بررسی می‌شوند. اتصال مستقیم به Binance WebSocket انجام می‌شود.</p>'+watchlistStatic()+'</div></div>';
}
function startLivePrices() {
  renderLiveTiles();
  const streams = state.watchlist.filter(w=>w.exchange==='binance').map(w=>w.stream).join('/');
  if (!streams || liveSocket) return;
  liveSocket = new WebSocket('wss://stream.binance.com:9443/stream?streams=' + streams);
  liveSocket.onopen = () => { if ($('wsStatus')) $('wsStatus').textContent='متصل'; };
  liveSocket.onmessage = (event) => { const payload = JSON.parse(event.data); const d = payload.data || {}; livePrices[d.s] = { price: Number(d.c), change: Number(d.P), high: Number(d.h), low: Number(d.l) }; renderLiveTiles(); };
  liveSocket.onerror = () => { if ($('wsStatus')) $('wsStatus').textContent='خطا / محدودیت شبکه'; };
  liveSocket.onclose = () => { liveSocket = null; if ($('wsStatus')) $('wsStatus').textContent='قطع'; };
}
function stopLivePrices() { if (liveSocket) { liveSocket.close(); liveSocket = null; } }
function renderLiveTiles() {
  if (!$('livePrices')) return;
  $('livePrices').innerHTML = state.watchlist.map(w => { const p = livePrices[w.symbol] || {}; const ch = Number(p.change || 0); return '<div class="price-tile"><span><b>'+w.symbol+'</b><br><small>'+w.exchange+'</small></span><span><b>'+(p.price?fmt(p.price,4):'--')+'</b><br><small class="'+(ch>=0?'positive':'negative')+'">'+pct(ch)+'</small></span></div>'; }).join('');
}
function watchlistStatic() { return state.watchlist.map(w=>'<div class="price-tile"><span><b>'+w.symbol+'</b><br><small>'+w.exchange+'</small></span><span><small>▲ '+fmt(w.alertAbove)+'</small><br><small>▼ '+fmt(w.alertBelow)+'</small></span></div>').join(''); }

function accounts() {
  const stats = computeStats();
  return '<div class="grid"><div class="card span-12"><div class="card-header"><h3>مدیریت چند حساب</h3><button class="btn" onclick="openAccountModal()">+ حساب</button></div><div class="grid">'+state.accounts.map(a=>'<div class="card span-4"><span class="pill" style="border-color:'+a.color+'">'+escapeHtml(a.broker)+'</span><h2>'+escapeHtml(a.name)+'</h2><p class="muted">'+a.type+' • '+a.currency+'</p><div class="kpi">'+money(a.balance)+'</div><p class="'+(a.balance>=a.startingBalance?'positive':'negative')+'">بازده: '+pct((a.balance-a.startingBalance)/a.startingBalance*100)+'</p></div>').join('')+'</div></div>'+kpiCard('کل سرمایه', money(stats.equity), 'span-4')+kpiCard('شروع کل', money(stats.totalStart), 'span-4')+kpiCard('بازده کل', pct((stats.equity-stats.totalStart)/(stats.totalStart||1)*100), 'span-4')+'</div>';
}

function playbook() {
  return '<div class="grid"><div class="card span-12"><h3>پلی‌بوک عملیاتی</h3><div class="kanban">'+state.playbooks.map(pb=>'<div class="lane"><h4>'+escapeHtml(pb.title)+'</h4>'+pb.items.map(item=>'<label class="check-item"><input type="checkbox"><span>'+escapeHtml(item)+'</span></label>').join('')+'</div>').join('')+'</div></div></div>';
}

function settings() {
  return '<div class="grid"><div class="card span-6"><h3>تنظیمات اصلی</h3><div class="form-grid">'+field('setRisk','ریسک هر معامله %','number',state.settings.riskPerTrade)+field('setDaily','حد ضرر روزانه %','number',state.settings.maxDailyLoss)+field('setCurrency','ارز پایه','text',state.settings.baseCurrency)+'<div class="field full"><button class="btn primary" onclick="updateSettings()">ذخیره تنظیمات</button></div></div></div><div class="card span-6"><h3>Data Ops</h3><p class="muted">خروجی، ایمپورت، ریست و health-check از همین Worker انجام می‌شود.</p><div class="toolbar"><button class="btn" onclick="exportState()">Export</button><button class="btn danger" onclick="resetState()">Reset Seed</button><a class="btn" href="/health" target="_blank">Health</a></div></div></div>';
}
function updateSettings() { state.settings.riskPerTrade = Number($('setRisk').value); state.settings.maxDailyLoss = Number($('setDaily').value); state.settings.baseCurrency = $('setCurrency').value; saveState(); }

function openTradeModal(existing) {
  const t = existing || { id:'', accountId: state.accounts[0]?.id, symbol:'', market:'Crypto', side:'Long', setup:'', timeframe:'15m', entry:'', exit:'', stop:'', qty:'', fees:0, discipline:8, confidence:7, emotionBefore:'', emotionAfter:'', tags:[], notes:'', mistakes:'', openedAt:new Date().toISOString().slice(0,16), closedAt:new Date().toISOString().slice(0,16) };
  const accounts = state.accounts.map(a=>'<option value="'+a.id+'" '+(a.id===t.accountId?'selected':'')+'>'+a.name+'</option>').join('');
  openModal('<div class="card-header"><h3>'+(existing?'ویرایش معامله':'معامله جدید')+'</h3><button class="btn" onclick="closeModal()">بستن</button></div><div class="form-grid">'+
    '<div class="field"><label>حساب</label><select id="mAccount">'+accounts+'</select></div>'+input('mSymbol','نماد',t.symbol)+input('mMarket','بازار',t.market)+select('mSide','جهت',['Long','Short'],t.side)+input('mSetup','ستاپ',t.setup)+input('mTf','تایم‌فریم',t.timeframe)+input('mEntry','ورود',t.entry,'number')+input('mExit','خروج',t.exit,'number')+input('mStop','استاپ',t.stop,'number')+input('mQty','حجم',t.qty,'number')+input('mFees','کارمزد',t.fees,'number')+input('mDisc','انضباط 1-10',t.discipline,'number')+input('mConf','اعتماد 1-10',t.confidence,'number')+input('mBefore','احساس قبل',t.emotionBefore)+input('mAfter','احساس بعد',t.emotionAfter)+'<div class="field"><label>زمان ورود</label><input id="mOpen" type="datetime-local" value="'+String(t.openedAt||'').slice(0,16)+'"></div><div class="field"><label>زمان خروج</label><input id="mClose" type="datetime-local" value="'+String(t.closedAt||'').slice(0,16)+'"></div><div class="field full"><label>یادداشت</label><textarea id="mNotes">'+escapeHtml(t.notes||'')+'</textarea></div><div class="field full"><label>اشتباهات</label><textarea id="mMistakes">'+escapeHtml(t.mistakes||'')+'</textarea></div><div class="field full"><button class="btn primary" onclick="submitTrade(\''+(t.id||'')+'\')">ذخیره معامله</button></div></div>');
}
function input(id,label,value,type='text') { return '<div class="field"><label>'+label+'</label><input id="'+id+'" type="'+type+'" value="'+escapeAttr(value)+'" step="any"></div>'; }
function select(id,label,options,value) { return '<div class="field"><label>'+label+'</label><select id="'+id+'">'+options.map(o=>'<option '+(o===value?'selected':'')+'>'+o+'</option>').join('')+'</select></div>'; }
function submitTrade(id) {
  const trade = { id: id || uid('trd'), accountId:$('mAccount').value, symbol:$('mSymbol').value.toUpperCase(), market:$('mMarket').value, side:$('mSide').value, setup:$('mSetup').value, timeframe:$('mTf').value, entry:Number($('mEntry').value), exit:Number($('mExit').value), stop:Number($('mStop').value), qty:Number($('mQty').value), fees:Number($('mFees').value), discipline:Number($('mDisc').value), confidence:Number($('mConf').value), emotionBefore:$('mBefore').value, emotionAfter:$('mAfter').value, openedAt:new Date($('mOpen').value).toISOString(), closedAt:new Date($('mClose').value).toISOString(), notes:$('mNotes').value, mistakes:$('mMistakes').value, tags:[] };
  const idx = state.trades.findIndex(t=>t.id===id); if (idx>=0) state.trades[idx]=trade; else state.trades.unshift(trade); closeModal(); saveState();
}
function editTrade(id) { openTradeModal(state.trades.find(t=>t.id===id)); }
function deleteTrade(id) { if (confirm('حذف شود؟')) { state.trades = state.trades.filter(t=>t.id!==id); saveState(); } }

function openJournalModal() { openModal('<div class="card-header"><h3>ثبت روزانه روانشناسی</h3><button class="btn" onclick="closeModal()">بستن</button></div><div class="form-grid">'+input('jDate','تاریخ',new Date().toISOString().slice(0,10),'date')+input('jMood','مود',7,'number')+input('jStress','استرس',3,'number')+input('jSleep','خواب',7,'number')+input('jFocus','تمرکز',8,'number')+'<div class="field full"><label>بایاس بازار</label><textarea id="jBias"></textarea></div><div class="field full"><label>پلن</label><textarea id="jPlan"></textarea></div><div class="field full"><label>بازبینی</label><textarea id="jReview"></textarea></div><div class="field full"><button class="btn primary" onclick="submitJournal()">ذخیره</button></div></div>'); }
function submitJournal() { state.journal.unshift({ id:uid('jr'), date:$('jDate').value, mood:Number($('jMood').value), stress:Number($('jStress').value), sleep:Number($('jSleep').value), focus:Number($('jFocus').value), marketBias:$('jBias').value, plan:$('jPlan').value, review:$('jReview').value }); closeModal(); saveState(); }
function openEventModal() { openModal('<div class="card-header"><h3>رویداد جدید</h3><button class="btn" onclick="closeModal()">بستن</button></div><div class="form-grid">'+input('eDate','تاریخ',new Date().toISOString().slice(0,10),'date')+input('eTime','ساعت','16:00','time')+input('eCurrency','ارز','USD')+select('eImpact','اهمیت',['High','Medium','Low'],'High')+input('eTitle','عنوان','')+'<div class="field full"><label>پلن</label><textarea id="ePlan"></textarea></div><div class="field full"><button class="btn primary" onclick="submitEvent()">ذخیره</button></div></div>'); }
function submitEvent() { state.events.unshift({ id:uid('ev'), date:$('eDate').value, time:$('eTime').value, currency:$('eCurrency').value, impact:$('eImpact').value, title:$('eTitle').value, plan:$('ePlan').value }); closeModal(); saveState(); }
function openAccountModal() { openModal('<div class="card-header"><h3>حساب جدید</h3><button class="btn" onclick="closeModal()">بستن</button></div><div class="form-grid">'+input('aName','نام حساب','')+input('aBroker','بروکر','')+input('aType','نوع','Futures')+input('aCurrency','ارز','USDT')+input('aBalance','بالانس','10000','number')+input('aStart','شروع','10000','number')+'<div class="field full"><button class="btn primary" onclick="submitAccount()">ذخیره</button></div></div>'); }
function submitAccount() { state.accounts.push({ id:uid('acc'), name:$('aName').value, broker:$('aBroker').value, type:$('aType').value, currency:$('aCurrency').value, balance:Number($('aBalance').value), startingBalance:Number($('aStart').value), leverageLimit:1, color:'#8b5cf6', createdAt:new Date().toISOString() }); closeModal(); saveState(); }

function openModal(html) { $('modalContent').innerHTML = html; $('modal').classList.add('active'); }
function closeModal() { $('modal').classList.remove('active'); $('modalContent').innerHTML = ''; }
function filterItems(items, keys) { if (!searchTerm) return items; return items.filter(item => keys.some(k => String(item[k]||'').toLowerCase().includes(searchTerm))); }
function drawEquitySparkline(id, curve) { const svg = $(id); if (!svg) return; const w=640,h=80,p=8,min=Math.min(...curve),max=Math.max(...curve),range=max-min||1; const pts=curve.map((v,i)=>[p+i*(w-2*p)/(curve.length-1||1), h-p-(v-min)*(h-2*p)/range]); svg.setAttribute('viewBox','0 0 '+w+' '+h); svg.innerHTML='<defs><linearGradient id="g'+id+'" x1="0" x2="1"><stop stop-color="#8b5cf6"/><stop offset="1" stop-color="#06b6d4"/></linearGradient></defs><polyline fill="none" stroke="url(#g'+id+')" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" points="'+pts.map(p=>p.join(',')).join(' ')+'"/><path fill="rgba(139,92,246,.12)" d="M '+pts.map(p=>p.join(' ')).join(' L ')+' L '+(w-p)+' '+h+' L '+p+' '+h+' Z"/>'; }
async function exportState() { const blob = new Blob([JSON.stringify(state,null,2)], { type:'application/json' }); const a = document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='trading-journal.json'; a.click(); URL.revokeObjectURL(a.href); }
async function importState(event) { const file = event.target.files[0]; if (!file) return; state = JSON.parse(await file.text()); await saveState(); toast('ایمپورت شد'); }
async function resetState() { if (!confirm('همه داده‌ها با seed اولیه جایگزین شود؟')) return; const res = await fetch('/api/reset'+location.search, { method:'POST' }); const payload = await res.json(); state = payload.state; renderAll(); toast('ریست شد'); }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>"]/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[s])); }
function escapeAttr(value) { return escapeHtml(value).replace(/'/g, '&#39;'); }
</script>
</body>
</html>`;
}
